from __future__ import annotations

from dataclasses import dataclass, field
from typing import Any

import pytest

from llm_router._api.errors import ProviderError
from llm_router._api.types import Model, Provider, ToolCall
from llm_router._internal.config import RetryPolicy
from llm_router._internal.providers.base import (
    ProviderCapabilities,
    ProviderRequest,
    ProviderResult,
)
from llm_router._internal.runtime.errors import AttemptLeftError
from llm_router._internal.runtime.executor import ProviderRouteExecutor

pytestmark = pytest.mark.verification_kind("unit")


class LeftFlag:
    """The part of an event the executor reads and the adapter sets."""

    def __init__(self) -> None:
        self.flag = False

    def set(self) -> None:
        self.flag = True

    def is_set(self) -> bool:
        return self.flag


def dummy_tool(query: str = "") -> str:
    """A dummy tool."""
    return query


@dataclass(frozen=True)
class Config:
    retry_policy: RetryPolicy


@dataclass(frozen=True)
class Route:
    route_index: int = 0
    model: Model = Model.LLAMA_8B
    provider: Provider = Provider.GROQ
    provider_model: str = "llama-3.1-8b-instant"


@dataclass(frozen=True)
class Settings:
    temperature: float | None = None
    seed: int | None = None
    response_schema: object | None = {"type": "object"}
    tools: tuple[object, ...] | None = (dummy_tool,)
    tool_choice: str | None = "auto"
    max_tool_rounds: int | None = 2
    kwargs: dict[str, Any] = field(default_factory=dict)


@dataclass(frozen=True)
class Credential:
    key_id: int = 1
    env_var: str = "GROQ_API_ENV"
    value: str = "v"


@dataclass(frozen=True)
class Resolved:
    request_id: str = "req-1"
    route: Route = field(default_factory=Route)
    settings: Settings = field(default_factory=Settings)
    key: Credential = field(default_factory=Credential)
    messages: tuple[str, ...] = ("hello",)
    content: object = "hello"


CAPABILITIES = ProviderCapabilities(
    supports_images=True,
    supports_files=True,
    supports_video_file=False,
    supports_video_url=False,
    supports_json_schema=True,
    supports_tools=True,
)


class LateToolAdapter:
    """Returns a tool call while simulating an attempt that timed out."""

    def __init__(self, left: LeftFlag) -> None:
        self.capabilities = CAPABILITIES
        self.left = left
        self.sync_calls = 0
        self.async_calls = 0

    def execute(self, request: ProviderRequest) -> ProviderResult:
        self.sync_calls += 1
        self.left.set()
        return ProviderResult(
            data={},
            provider=Provider.GROQ,
            model=Model.LLAMA_8B,
            provider_model="llama-3.1-8b-instant",
            output_text="",
            tool_calls=(ToolCall(id="call-1", name="dummy_tool", args={"query": "test"}),),
        )

    async def aexecute(self, request: ProviderRequest) -> ProviderResult:
        self.async_calls += 1
        self.left.set()
        return ProviderResult(
            data={},
            provider=Provider.GROQ,
            model=Model.LLAMA_8B,
            provider_model="llama-3.1-8b-instant",
            output_text="",
            tool_calls=(ToolCall(id="call-1", name="dummy_tool", args={"query": "test"}),),
        )


def build_executor(adapter: LateToolAdapter) -> ProviderRouteExecutor:
    def getter(_provider: Provider, _config: object) -> LateToolAdapter:
        return adapter

    policy = RetryPolicy(min_wait_seconds=0.0, max_wait_seconds=0.0, max_attempts=3)
    return ProviderRouteExecutor(
        config=Config(retry_policy=policy),  # type: ignore[arg-type]
        adapter_getter=getter,  # type: ignore[arg-type]
    )


@pytest.mark.asyncio
@pytest.mark.verifies("TREQ_TIMED_OUT_ATTEMPT_STOPS[revision==1]")
async def test_late_tool_call_runs_no_tool_and_capabilities_read() -> None:
    left = LeftFlag()
    adapter = LateToolAdapter(left)
    executor = build_executor(adapter)
    resolved = Resolved()

    try:
        executor.execute(resolved, left=left)  # type: ignore[arg-type]
    except ProviderError as e:
        if not isinstance(e.__cause__, AttemptLeftError):
            raise

    assert adapter.sync_calls == 1

    left_async = LeftFlag()
    adapter_async = LateToolAdapter(left_async)
    executor_async = build_executor(adapter_async)

    try:
        await executor_async.aexecute(resolved, left=left_async)  # type: ignore[arg-type,call-arg]
    except TypeError:
        await executor_async.aexecute(resolved)  # type: ignore[arg-type]
    except ProviderError as e:
        if not isinstance(e.__cause__, AttemptLeftError):
            raise

    assert adapter_async.async_calls == 1
